begin;
set local role authenticated;select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
do $$
declare p uuid:='11111111-1111-4111-8111-111111111111';env jsonb;rev jsonb;started jsonb;old_run jsonb;replay jsonb;bad jsonb;policy jsonb:='{"schemaVersion":1,"interactions":[{"selector":"#menu","actions":["click"],"repeatable":true},{"selector":"#save","actions":["click"]}],"allowCoordinates":false}';
begin
 env:=public.save_dynamic_environment(p,'{"name":"Repeat consent fixture","targetUrl":"http://localhost:3000/","allowedOrigins":["http://localhost:3000"],"viewport":{"width":1280,"height":720},"accountRole":"fixture","requiredVariables":[],"startupInstructions":"Manual","targetVersion":"fixture"}'::jsonb||jsonb_build_object('actionPolicy',policy));if env->'actionPolicy' is distinct from policy then raise exception 'Repeat consent not saved';end if;
 foreach bad in array array['{"selector":"#x","actions":["type"],"repeatable":true}'::jsonb,'{"selector":"#x","actions":["click"],"repeatable":"yes"}','{"selector":"#x","actions":["click"],"repeatable":null}'] loop
  begin perform public.save_dynamic_environment(p,env||jsonb_build_object('actionPolicy',policy||jsonb_build_object('interactions',jsonb_build_array(bad))),(env->>'id')::uuid);raise exception 'Invalid repeat consent accepted';exception when raise_exception then if sqlerrm='Invalid repeat consent accepted' then raise;end if;end;
 end loop;
 perform public.record_dynamic_environment_data(p,(env->>'id')::uuid,'preparation','completed','Clean repeat fixture');rev:=public.save_dynamic_revision(p,auth.uid(),'{"name":"Repeat snapshot","goal":"Toggle menu","targetUrl":"http://localhost:3000/","maxSteps":3,"context":null,"checks":[{"id":"one","criterionId":"one","description":"Menu","kind":"visible_text","expected":"Ready","required":true}]}');
 started:=public.start_dynamic_environment_run(p,auth.uid(),(rev->>'id')::uuid,'repeat-consent-run',env||'{"variableNames":[],"preflight":[{"name":"ready","ready":true}],"actionPolicy":{"schemaVersion":1,"interactions":[{"selector":"#save","actions":["click"],"repeatable":true}],"allowCoordinates":true}}');old_run:=started->'run';if old_run->'actionPolicy' is distinct from policy or old_run->'executionVersions'->>'executor'<>'2' or old_run->'executionVersions'->>'policy'<>'2' then raise exception 'Forged repeat consent accepted or versions missing';end if;
 perform public.transition_dynamic_run(p,(old_run->>'id')::uuid,'queued','{"state":"cancelled","verdict":"not_tested","checks":[],"evidence":[]}');env:=public.save_dynamic_environment(p,env||'{"actionPolicy":{"schemaVersion":1,"interactions":[],"allowCoordinates":false}}',(env->>'id')::uuid);replay:=public.start_dynamic_environment_run(p,auth.uid(),(rev->>'id')::uuid,'repeat-consent-run',env);if replay->'run'->'actionPolicy' is distinct from policy then raise exception 'Historical repeat consent rewritten';end if;
 if has_function_privilege('authenticated','public.start_dynamic_run_without_repeat_guard_version(uuid,uuid,uuid,text)','execute') or has_function_privilege('authenticated','public.start_dynamic_environment_run_without_repeat_guard_version(uuid,uuid,uuid,text,jsonb)','execute') then raise exception 'Private repeat helpers exposed';end if;
 raise notice 'PASS: explicit bounded repeat consent, SQL authority, engine versions and immutable replay';
end $$;
rollback;
